#include <WiFi.h>
#include "esp_wifi.h"

const char* ssids[] = {
  "Free_WiFi_1",
  "Free_WiFi_2",
  "Free_WiFi_3",
  "Free_WiFi_4",
  "Free_WiFi_5",
  "Free_WiFi_6",
  "Free_WiFi_7",
  "Free_WiFi_8",
  "Free_WiFi_9",
  "Free_WiFi_10",
  "Free_WiFi_11",
  "Free_WiFi_12",
  "Free_WiFi_13",
  "Free_WiFi_14",
  "Free_WiFi_15",
  "Free_WiFi_16",
  "Free_WiFi_17",
  "Free_WiFi_18",
  "Free_WiFi_19",
  "Free_WiFi_20"
};

const int numSSIDs = sizeof(ssids) / sizeof(ssids[0]);

void setup() {
  Serial.begin(115200);
  Serial.println("เริ่มปล่อยหลายชื่อ...");

  WiFi.mode(WIFI_AP);
  WiFi.softAP("hidden", NULL, 20, false); // ซ่อนชื่อจริง
}

void loop() {
  // ส่งซ้ำหลายรอบติดกัน เพื่อให้ชื่อค้างนาน
  for (int round = 0; round < 5; round++) {
    for (int i = 0; i < numSSIDs; i++) {
      sendBeacon(ssids[i], i);
    }
  }
}

void sendBeacon(const char* ssid, uint8_t id) {
  uint8_t packet[128] = {0};
  int pos = 0;

  packet[pos++] = 0x80;
  packet[pos++] = 0x00;
  packet[pos++] = 0x00;
  packet[pos++] = 0x00;

  // Broadcast
  memset(&packet[pos], 0xff, 6);
  pos += 6;

  // Source + BSSID ต่างกันแต่ละชื่อ
  packet[pos++] = 0xDE;
  packet[pos++] = 0xAD;
  packet[pos++] = 0xBE;
  packet[pos++] = 0xEF;
  packet[pos++] = 0x00;
  packet[pos++] = id;

  packet[pos++] = 0xDE;
  packet[pos++] = 0xAD;
  packet[pos++] = 0xBE;
  packet[pos++] = 0xEF;
  packet[pos++] = 0x00;
  packet[pos++] = id;

  packet[pos++] = 0x00;
  packet[pos++] = 0x00;

  memset(&packet[pos], 0, 8); // Timestamp
  pos += 8;

  packet[pos++] = 0x64; // Beacon interval
  packet[pos++] = 0x00;
  packet[pos++] = 0x21; // Capability (Privacy)
  packet[pos++] = 0x04;

  // SSID
  int len = strlen(ssid);
  if (len > 32) len = 32;
  packet[pos++] = 0x00;
  packet[pos++] = len;
  memcpy(&packet[pos], ssid, len);
  pos += len;

  // Supported Rates
  packet[pos++] = 0x01;
  packet[pos++] = 8;
  packet[pos++] = 0x82; packet[pos++] = 0x84;
  packet[pos++] = 0x8b; packet[pos++] = 0x96;
  packet[pos++] = 0x24; packet[pos++] = 0x30;
  packet[pos++] = 0x48; packet[pos++] = 0x6c;

  esp_wifi_80211_tx(WIFI_IF_AP, packet, pos, false);
}
